<template> 
  <view class="schedule-page"> 
    <view class="doctor-header">
      <view class="doctor-info">
        <text class="doctor-name">{{ doctorInfo.name || '张医生' }}</text>
        <text class="doctor-dept">{{ doctorInfo.department || '内科' }}</text>
      </view>
      <text class="today-date">{{ todayDate }}</text>
    </view>

    <view class="date-selector">
      <scroll-view scroll-x class="date-scroll">
        <view
          v-for="(date, index) in dateList"
          :key="index"
          class="date-item"
          :class="{ active: selectedDateIndex === index }"
          @click="selectDate(index)"
        >
          <text class="date-weekday">{{ date.weekday }}</text>
          <text class="date-day">{{ date.day }}</text>
          <text class="date-month">{{ date.month }}</text>
        </view>
      </scroll-view>
    </view>

    <view class="schedule-container">
      <view class="section-title">
        <text class="title-text">当日出诊排班</text>
      </view>

      <view v-if="scheduleList.length === 0" class="empty-state">
        <text class="empty-text">暂无排班信息</text>
      </view>

      <view v-else class="schedule-list">
        <view
          v-for="(item, index) in scheduleList"
          :key="index"
          class="schedule-item"
        >
          <view class="schedule-header">
            <view class="time-period">
              <text class="period-icon">⏰</text>
              <text class="period-text">{{ item.timePeriod }}</text>
            </view>
            <view class="status-tag" :class="getStatusClass(item)">
              {{ getStatusText(item) }}
            </view>
          </view>

          <view class="schedule-info">
            <view class="info-item">
              <text class="info-label">诊室号：</text>
              <text class="info-value">{{ item.roomNumber }}</text>
            </view>
            <view class="info-item">
              <text class="info-label">可预约：</text>
              <text class="info-value">{{ item.totalSlots }}人</text>
            </view>
            <view class="info-item">
              <text class="info-label">已挂号：</text>
              <text class="info-value appointment-count">{{ item.bookedSlots }}人</text>
            </view>
            <view class="info-item">
              <text class="info-label">剩余号源：</text>
              <text class="info-value remaining" :class="{ 'low-remaining': item.remainingSlots < 3 }">
                {{ item.remainingSlots }}人
              </text>
            </view>
          </view>
        </view>
      </view>
    </view>

    <view class="action-section">
      <button class="action-btn adjust-btn" @click="goToAdjustSchedule">
        申请调班
      </button>
    </view>

    <view class="bottom-nav">
      <view class="nav-item" @click="goToPatients">
        <text class="nav-icon">👥</text>
        <text class="nav-text">患者详情</text>
      </view>
      <view class="nav-item" @click="goToProfile">
        <text class="nav-icon">👤</text>
        <text class="nav-text">个人信息</text>
      </view>
    </view>
  </view>
</template>

<script setup>
import { ref, onMounted } from 'vue'
// 假设 uniNavigateTo, uniShowToast, scheduleApi 已经正确导入
// import { uniNavigateTo, uniShowToast } from '../../../utils/uniHelper'
// import { scheduleApi } from '../../../api/schedule'

// ====== 辅助函数 START ======

// 简单的日期格式化函数
const formatDate = (date) => {
    const yyyy = date.getFullYear()
    const mm = String(date.getMonth() + 1).padStart(2, '0')
    const dd = String(date.getDate()).padStart(2, '0')
    return `${yyyy}-${mm}-${dd}`
}

// ====== 辅助函数 END ======


// 医生信息（如需从用户状态中取，可替换为 pinia 的 userStore）
const doctorInfo = ref({
  name: '张医生',
  department: '内科'
})

// 当前日期
const todayDate = ref('')

// 日期列表（未来7天）
const dateList = ref([])
const selectedDateIndex = ref(0)

// 排班列表
const scheduleList = ref([])

// 初始化日期列表
const initDateList = () => {
  const dates = []
  const weekdays = ['周日', '周一', '周二', '周三', '周四', '周五', '周六']
  const today = new Date()

  for (let i = 0; i < 7; i++) {
    const date = new Date(today) // 克隆日期对象，避免引用问题
    date.setDate(today.getDate() + i)
    dates.push({
      weekday: weekdays[date.getDay()],
      day: date.getDate(),
      month: `${date.getMonth() + 1}月`,
      fullDate: date,
      dateStr: formatDate(date) // 添加格式化后的日期字符串
    })
  }
  dateList.value = dates

  // 设置顶部的今天日期
  todayDate.value = `${today.getFullYear()}年${today.getMonth() + 1}月${today.getDate()}日`
}

// 选择日期
const selectDate = (index) => {
  if (selectedDateIndex.value === index) return
  selectedDateIndex.value = index
  loadScheduleData()
}

// 映射：time_slot code -> 展示配置
// 假设 typeId 是排班类型（普通/专家）， time_slot 才是上午/下午的代号
const TIME_SLOT_MAP = {
  // 假设 1=上午, 2=下午, 3=晚上
  1: { label: '上午 08:00-12:00', defaultTotalSlots: 20 },
  2: { label: '下午 14:00-17:00', defaultTotalSlots: 15 },
  3: { label: '晚上 18:00-20:00', defaultTotalSlots: 10 },
}

/**
 * 将后端返回的排班数据转换为页面展示需要的结构
 * @param {Object} raw - 原始数据 (例如: { timeSlot: 1, usedQuota: 5, deptId: 20 })
 */
const normalizeSchedule = (raw) => {
  // 使用 timeSlot 代号来查找配置
  const cfg = TIME_SLOT_MAP[raw.timeSlot] || { label: raw.timeSlot || '未知时段', defaultTotalSlots: 10 }

  // 实际可预约号源 totalSlots 应该从后端获取，如果后端没有，则使用默认值
  // 假设后端 totalSlots 字段为 totalQuota (请根据实际后端字段名修改)
  const total = Number(raw.totalQuota || cfg.defaultTotalSlots)
  const booked = Number(raw.usedQuota || 0)

  return {
    timePeriod: cfg.label,
    roomNumber: raw.roomNumber || (raw.deptId ? `门诊-${raw.deptId}` : '诊室'), // 假设后端有 roomNumber 字段
    totalSlots: total,
    bookedSlots: booked,
    remainingSlots: Math.max(total - booked, 0),
  }
}

// 加载排班数据（后端）
const loadScheduleData = async () => {
  // 获取当前选中的日期字符串
  const dateStr = dateList.value[selectedDateIndex.value]?.dateStr
  if (!dateStr) return

  try {
    // doctorId 实际应来自登录或用户信息，这里先用示例值 1
    const doctorId = 1

    // 假设 scheduleApi.getByDate 接收 doctorId 和日期字符串
    // 请确保 scheduleApi 已正确导入
    // const list = await scheduleApi.getByDate(doctorId, dateStr)

    // ===== 临时模拟数据 START (调试时使用，完成后请删除或注释) =====
    const mockRawData = [
        { timeSlot: 1, usedQuota: 5, totalQuota: 20, deptId: 20, roomNumber: '101' },
        { timeSlot: 2, usedQuota: 13, totalQuota: 15, deptId: 20, roomNumber: '101' },
        { timeSlot: 3, usedQuota: 5, totalQuota: 10, deptId: 25, roomNumber: '102' },
    ];
    let list = (selectedDateIndex.value === 0) ? mockRawData : mockRawData.map(item => ({
        ...item,
        usedQuota: Math.floor(item.usedQuota * 0.5) // 模拟其他日期号源较少
    }));
    // ===== 临时模拟数据 END =====


    scheduleList.value = Array.isArray(list) ? list.map(normalizeSchedule) : []

  } catch (e) {
    console.error(`加载 ${dateStr} 排班失败`, e)
    // 假设 uniShowToast 已导入
    // uniShowToast('加载排班失败')
    scheduleList.value = []
  }
}

// 获取状态样式类
const getStatusClass = (item) => {
  const rate = item.bookedSlots / item.totalSlots
  if (rate >= 0.9) return 'status-full'
  if (rate >= 0.6) return 'status-busy'
  return 'status-available'
}

// 获取状态文本
const getStatusText = (item) => {
  const rate = item.bookedSlots / item.totalSlots
  if (rate >= 0.9) return '号源紧张'
  if (rate >= 0.6) return '预约较多'
  return '可预约'
}

// 跳转到申请调班（映射到已存在的页面路径）
const goToAdjustSchedule = () => {
  // 假设 uniNavigateTo 已导入
  // uniNavigateTo({ url: '/pages/doctor/schedule/apply' })
  console.log('跳转到：/pages/doctor/schedule/apply')
}

// 跳转到患者列表（映射到已存在的页面路径）
const goToPatients = () => {
  // 假设 uniNavigateTo 已导入
  // uniNavigateTo({ url: '/pages/doctor/patients/list' })
  console.log('跳转到：/pages/doctor/patients/list')
}

// 跳转到个人信息（映射到已存在的页面路径）
const goToProfile = () => {
  // 假设 uniNavigateTo 已导入
  // uniNavigateTo({ url: '/pages/doctor/profile/index' })
  console.log('跳转到：/pages/doctor/profile/index')
}

onMounted(() => {
  initDateList()
  // 第一次加载数据
  loadScheduleData()
})
</script>

