  display: inline-flex; 
  flex-direction: column; 
  align-items: center; 
  justify-content: center; 
  width: 120rpx; 
  height: 120rpx; 
  margin-right: 12rpx; 
  background: #f1f5f9; 
  border-radius: 16rpx; 
  box-shadow: 0 4rpx 12rpx rgba(33,118,255,0.06); 
  color: #334155; 
} 
.date-item.active { 
  background: linear-gradient(180deg, #e6f1ff 0%, #ffffff 100%); 
