  border-radius: 12rpx; 
  padding: 16rpx 0; 
  text-align: center; 
  box-shadow: 0 6rpx 16rpx rgba(33,118,255,0.18); 
} 
.nav-icon { display: block; font-size: 28rpx; } 
.nav-text { display: block; font-size: 26rpx; font-weight: 600; margin-top: 6rpx; } 
</style>